    for (const [taskIndex, visible] of state.results.entries()) {
        if (!visible) continue;
        commitsByRecord[tasks[taskIndex].recordIndex].push(visible);
    }

    return records.map((record, recordIndex) => ({ ...record, commits: commitsByRecord[recordIndex] }));
